import csv, json

def rank_by_feature(testfile, feat):
    test=list(csv.DictReader(open('data/'+testfile)))
    groups={}
    for r in test:
        groups.setdefault(r['query_id'],[]).append(r)
    out={}
    for q,rs in groups.items():
        rs2=sorted(rs,key=lambda r: float(r[feat]), reverse=True)
        out[q]=[r['doc_id'] for r in rs2]
    return out

sensor_pred=[1 if abs(float(r['value']))>2.0 else 0 for r in csv.DictReader(open('data/sensor_test.csv'))]
net_pred=[1 if float(r['src_bytes'])>1000 or float(r['dst_bytes'])>1000 else 0 for r in csv.DictReader(open('data/network_test.csv'))]

res={"sensor":sensor_pred,
     "network":net_pred,
     "movie_rank":rank_by_feature('movie_test.csv','year'),
     "news_rank":rank_by_feature('news_test.csv','length'),
     "both_rank":rank_by_feature('both_test.csv','score')}
json.dump(res,open('results.json','w'),indent=1)
print("sensor pos:",sum(sensor_pred),"of",len(sensor_pred))
print("network pos:",sum(net_pred),"of",len(net_pred))
for k in ["movie_rank","news_rank","both_rank"]:
    print(k, list(res[k].keys()), [len(v) for v in res[k].values()])
